INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0003-000000000001', 'Kotlin은 무엇이며 Java와 무엇이 다른가요?', 'EASY', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000002', '코틀린에서 널 안전성(null safety)은 어떻게 보장되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000003', '데이터 클래스(Data Class)란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000004', '확장 함수(Extension Function)란 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000005', '고차 함수(Higher-order function)와 람다(lambda)에 대해 설명해 주세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000006', '코루틴(Coroutine)은 무엇이고 어떻게 사용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000007', 'suspend 함수는 무엇이며 어디에 사용되나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000008', '스코프 함수(scope function)란 무엇이고, apply, let, run, also 등의 차이는?', 'HARD',   'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000009', 'sealed 클래스란 무엇이며 언제 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000010', '데스트럭처링(Destructuring) 선언은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000011', 'inline 함수는 무엇이며 어떤 경우에 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000012', '코틀린 DSL이란 무엇이며, 활용 사례는 어떤 것이 있나요?', 'HARD',   'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000013', '코틀린 JS나 코틀린 네이티브에 대해 들어본 적이 있나요? 각각 무엇인가요?', 'HARD',   'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000014', '코틀린의 표준 라이브러리 함수인 apply, let, run, also의 용도 차이는?', 'HARD',   'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000015', '코틀린에서의 예외 처리는 검사 예외가 없는 점을 제외하면 Java와 비슷한가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000003'),
('b0000000-0000-0000-0003-000000000016', '타입 추론(Type Inference)이란 무엇이며 코틀린은 어느 정도까지 지원하나요?', 'EASY',   'b0000000-0000-0000-0000-000000000003');
